// Does a converted entry point still hand a CAPTURING caller its whole output?
//
// Usage: node repro-truncation.mjs <script.mjs> <rounds>
//
// Drives the script through spawnSync — which is a PIPE, the condition the hazard
// needs — and counts the bytes that came back against the bytes it should have
// produced. The store fixture is a preferences file of a known size, so "complete"
// is an exact number rather than a judgement.
import { spawnSync } from 'node:child_process';
import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const script = process.argv[2];
const rounds = Number(process.argv[3] ?? 40);

const EMAIL = 'someone@example.com';
const root = join(process.env.SCRATCH ?? '/tmp', 'prefs-store');
mkdirSync(join(root, 'preferences'), { recursive: true });

// ~64 KiB of preferences: several pipe buffers' worth, so a dropped flush is
// visible rather than a coin flip. Numbered lines, so a short answer says where it
// was cut.
const body = Array.from({ length: 1200 }, (_, i) => `- preference line ${i}: ${'x'.repeat(40)}`).join('\n');
writeFileSync(join(root, 'preferences', `${EMAIL}.md`), `${body}\n`);
const expected = Buffer.byteLength(`${body}\n`);

const env = {
  ...process.env,
  CLAUDE_PROJECT_DIR: root,
  CLAUDINITE_PACK_CONFIG: JSON.stringify({ repo: 'owner/store', path: 'preferences' }),
  CLAUDE_CODE_USER_EMAIL: EMAIL,
  CLAUDE_CODE_SESSION_ATTENDED: '1',
};

let complete = 0;
const short = [];
for (let i = 0; i < rounds; i += 1) {
  const run = spawnSync(process.execPath, [script], { env, encoding: 'buffer', maxBuffer: 64 * 1024 * 1024 });
  // The step's own facet line goes out ahead of the file; the file is the tail.
  const out = run.stdout ?? Buffer.alloc(0);
  if (out.length >= expected) complete += 1;
  else short.push({ round: i, got: out.length, status: run.status });
}

console.log(`${script}`);
console.log(`  expected >= ${expected} bytes of preferences per run`);
console.log(`  complete: ${complete}/${rounds}`);
if (short.length) {
  console.log(`  SHORT: ${short.length} run(s) — ${short.slice(0, 6).map((s) => `#${s.round} got ${s.got} (exit ${s.status})`).join(', ')}`);
}

